 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        cells.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def _l_info(cells):
    if len(cells) < 3:
        return None
    for cr in {r for r, _ in cells}:
        for cc in {c for _, c in cells}:
            if not all(r == cr or c == cc for r, c in cells):
                continue
            vertical = sorted(r for r, c in cells if c == cc)
            horizontal = sorted(c for r, c in cells if r == cr)
            if len(vertical) + len(horizontal) - 1 != len(cells):
                continue
            vr = -1 if min(vertical) < cr else 1
            hc = -1 if min(horizontal) < cc else 1
            return cr, cc, vr, hc
    return None


def transform(grid):
    comps = _components(grid)
    ls = [(color, cells, _l_info(cells)) for color, cells in comps]
    ls = [item for item in ls if item[2] is not None]
    if not ls:
        return [row[:] for row in grid]

    # The prominent (largest) L is the color marker; its empty quadrant points
    # toward the component whose color should change to the marker color.
    key_color, key, (cr, cc, vr, hc) = max(ls, key=lambda item: len(item[1]))
    choices = []
    for color, cells in comps:
        if cells == key:
            continue
        cy = sum(r for r, _ in cells) / len(cells)
        cx = sum(c for _, c in cells) / len(cells)
        if (cy - cr) * vr < 0 and (cx - cc) * hc < 0:
            dist = (cy - cr) ** 2 + (cx - cc) ** 2
            choices.append((dist, cells))
    if not choices:
        return [row[:] for row in grid]
    target = min(choices, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out


